syntax:
SELECT columns
FROM table1
[INNER|LEFT|RIGHT|FULL] JOIN table2 ON table1.col = table2.col;

example:
SELECT users.name, orders.total
FROM users
LEFT JOIN orders ON users.id = orders.user_id;

syntax:
SELECT column, AGG_FUNC(other_column)
FROM table
GROUP BY column;

example:
SELECT city, COUNT(*) AS user_count
FROM users
GROUP BY city;

UPDATE products
SET price = price * 0.9
WHERE category = 'clearance';

syntax:
CREATE TABLE table_name (
  column1 TYPE constraints,
  column2 TYPE constraints
);

example:
CREATE TABLE orders (
  id SERIAL PRIMARY KEY,
  user_id INT NOT NULL REFERENCES users(id),
  total DECIMAL(10,2) NOT NULL,
  created_at TIMESTAMP DEFAULT NOW()
);

syntax:
WITH cte_name AS (
  SELECT ...
)
SELECT ... FROM cte_name;

example:
WITH big_orders AS (
  SELECT user_id, total FROM orders WHERE total > 1000
)
SELECT users.name, big_orders.total
FROM big_orders
JOIN users ON users.id = big_orders.user_id;
